#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

static void usage(void) {
    puts("USAGE");
}

int main(int argc, char **argv) {
    if (argc != 3) {
        usage();
        return 0;
    }
    /* Validate shift argument */
    const char *shift_str = argv[1];
    const char *p = shift_str;
    if (*p == '+' || *p == '-')
        p++;
    if (*p == '\0') {
        usage();
        return 0;
    }
    while (*p) {
        if (!isdigit((unsigned char)*p)) {
            usage();
            return 0;
        }
        p++;
    }
    char *endptr;
    long shift_val = strtol(shift_str, &endptr, 10);
    /* Compute shift modulo 26 in the range 0..25 */
    int shift = (int)((shift_val % 26 + 26) % 26);

    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > 1024) { // original limit 0x400
        usage();
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (isupper(c)) {
            putchar(((c - 'A' + shift) % 26) + 'A');
        } else if (islower(c)) {
            putchar(((c - 'a' + shift) % 26) + 'a');
        } else {
            putchar(c);
        }
    }
    putchar('\n');
    return 0;
}
